def register_shipment_events(event_type: str, events: list[str] | None = None) -> dict[str, list[str]]:
    if events is None:
        events = []
    events.append(event_type)
    return {event_type: list(events)}

def flag_large_backorder_totals(rows: list[dict[str, object]], threshold: float) -> list[dict[str, object]]:
    """Flag backorder rows whose total crosses the review threshold."""
    flagged: list[dict[str, object]] = []
    for row in rows:
        if float(row.get("total", 0)) > threshold:
            flagged.append(row)
    return flagged

